/**
 * SQLite → PostgreSQL DDL 生成器（P0 迁移用）。
 *
 * 只做**结构**转换，不碰数据：读 SQLite 的 PRAGMA 元信息，输出可直接在 PG 16 执行的 DDL。
 * 转换规则见 docs/postgres-migration.md，主要几条：
 *   - INTEGER PRIMARY KEY AUTOINCREMENT → bigint GENERATED BY DEFAULT AS IDENTITY
 *   - INTEGER/REAL/TEXT/BLOB → bigint(or integer)/double precision/text/bytea
 *   - DEFAULT (unixepoch()) → DEFAULT (EXTRACT(EPOCH FROM now()))::bigint
 *   - CHECK / UNIQUE / 部分索引 WHERE 原样保留（SQLite 语法与 PG 兼容）
 *   - COLLATE NOCASE → 用 lower() 表达式索引（由调用方在 DDL 后补）
 *   - 外键按 PRAGMA foreign_key_list 生成
 *
 * 用法（在 NAS 上）：
 *   node gen-schema.mjs <sqlite.db> <out.sql>
 */
import { DatabaseSync } from 'node:sqlite';
import { writeFileSync } from 'node:fs';

const dbPath = process.argv[2];
const outPath = process.argv[3] ?? '/tmp/schema.pg.sql';
if (!dbPath) {
  console.error('用法: node gen-schema.mjs <sqlite.db> <out.sql>');
  process.exit(2);
}

const db = new DatabaseSync(dbPath, { readOnly: true });

const tables = db
  .prepare("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
  .all();

const INT_TYPES = /^(integer|int|boolean|bigint|smallint|tinyint)\b/i;

/** SQLite 列默认值 → PG 表达式 */
function mapDefault(dflt, type) {
  if (dflt === null || dflt === undefined) return null;
  const v = String(dflt).trim();
  if (/^\(\s*unixepoch\(\)\s*\)$/i.test(v) || /^unixepoch\(\)$/i.test(v)) return '(EXTRACT(EPOCH FROM now()))::bigint';
  if (/^\(\s*datetime\('now'\)\s*\)$/i.test(v)) return 'now()';
  if (/^null$/i.test(v)) return 'NULL';
  if (/^-?\d+(\.\d+)?$/.test(v)) return v;
  if (/^'(.*)'$/.test(v)) return v; // 已经是 SQL 字符串字面量
  if (/^"(.*)"$/.test(v)) return `'${v.slice(1, -1)}'`;
  return null; // 复杂默认值不猜，交给人工
}

function mapType(type) {
  const t = String(type ?? '').toUpperCase();
  if (INT_TYPES.test(t)) return 'bigint';
  if (/^REAL|FLOAT|DOUBLE|NUMERIC|DECIMAL/.test(t)) return 'double precision';
  if (/^BLOB/.test(t)) return 'bytea';
  return 'text';
}

const lines = [];
lines.push('-- 由 ops/scripts/pg/gen-schema.mjs 从 SQLite schema 生成，勿手改');
lines.push('BEGIN;');
lines.push('');

const deferred = [];
const deferredFks = [];

for (const table of tables) {
  const cols = db.prepare(`PRAGMA table_info("${table.name}")`).all();
  const fks = db.prepare(`PRAGMA foreign_key_list("${table.name}")`).all();
  const pkCols = cols.filter((c) => c.pk > 0).sort((a, b) => a.pk - b.pk);

  const colDefs = [];
  let identityCol = null;
  for (const c of cols) {
    const type = mapType(c.type);
    const isIntPk = pkCols.length === 1 && pkCols[0].name === c.name && /INT/i.test(String(c.type));
    const parts = [`  "${c.name}"`, isIntPk ? 'bigint' : type];
    if (isIntPk) {
      // SQLite 的 INTEGER PRIMARY KEY 自带自增语义
      parts.push('GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY');
      identityCol = c.name;
    }
    if (c.notnull && !isIntPk) parts.push('NOT NULL');
    const def = isIntPk ? null : mapDefault(c.dflt_value, c.type);
    if (def !== null) parts.push(`DEFAULT ${def}`);
    colDefs.push(parts.join(' '));
  }
  if (pkCols.length > 1) {
    colDefs.push(`  PRIMARY KEY (${pkCols.map((c) => `"${c.name}"`).join(', ')})`);
  }

  // UNIQUE 约束（行内 UNIQUE 已包含在 sqlite 的 sql 里，这里用索引元信息兜底）
  const uniqueIdx = db
    .prepare(`PRAGMA index_list("${table.name}")`)
    .all()
    .filter((i) => i.unique === 1 && i.origin === 'u');
  for (const idx of uniqueIdx) {
    const colsOfIdx = db.prepare(`PRAGMA index_info("${idx.name}")`).all();
    deferred.push(
      `ALTER TABLE "${table.name}" ADD CONSTRAINT "${table.name}_${idx.name}_key" UNIQUE (${colsOfIdx
        .map((c) => `"${c.name}"`)
        .join(', ')});`,
    );
  }

  // 外键：**不在建表时内联**（PG 要求被引用表先存在，而 SQLite 允许任意顺序），
  // 全部延后到所有表建好之后用 ALTER TABLE 添加。
  const fkGroups = new Map();
  for (const fk of fks) {
    const key = `${fk.id}`;
    if (!fkGroups.has(key)) fkGroups.set(key, { table: fk.table, from: [], to: [] });
    const g = fkGroups.get(key);
    g.from.push(`"${fk.from}"`);
    g.to.push(`"${fk.to}"`);
  }
  for (const [id, g] of fkGroups) {
    deferredFks.push(
      `ALTER TABLE "${table.name}" ADD CONSTRAINT "${table.name}_fk_${id}" FOREIGN KEY (${g.from.join(
        ', ',
      )}) REFERENCES "${g.table}" (${g.to.join(', ')});`,
    );
  }

  // 行内 CHECK：从 sqlite 原文里抠出来（PG 语法兼容）
  const checks = [...String(table.sql).matchAll(/CHECK\s*\(((?:[^()]|\([^()]*\))*)\)/gi)].map((m) => m[1]);
  checks.forEach((expr, i) => colDefs.push(`  CONSTRAINT "${table.name}_check_${i + 1}" CHECK (${expr})`));

  lines.push(`CREATE TABLE "${table.name}" (`);
  lines.push(colDefs.join(',\n'));
  lines.push(');');
  lines.push('');
}

lines.push('-- 唯一约束（延后，避免建表顺序问题）');
lines.push(...deferred);
lines.push('');
lines.push('-- 外键（延后到最后，PG 要求被引用表先存在）');
lines.push(...deferredFks);
lines.push('');

// 索引（跳过 sqlite 自动索引与唯一索引）
const indexes = db
  .prepare(
    "SELECT name, tbl_name, sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL AND name NOT LIKE 'sqlite_autoindex%'",
  )
  .all();
lines.push('-- 索引');
for (const idx of indexes) {
  // 把 CREATE INDEX 里的表名/列名加引号，保持 WHERE 原样
  const m = /CREATE\s+(UNIQUE\s+)?INDEX\s+\S+\s+ON\s+([A-Za-z0-9_]+)\s*\(([^)]*)\)(.*)$/is.exec(idx.sql);
  if (!m) {
    lines.push(`-- 无法自动转换，请人工处理: ${idx.sql}`);
    continue;
  }
  const unique = m[1] ? 'UNIQUE ' : '';
  const colsPart = m[3]
    .split(',')
    .map((s) =>
      s
        .trim()
        // SQLite 的 COLLATE NOCASE 在 PG 由 citext 列类型承担（见 post-schema.pg.sql）
        .replace(/\s+COLLATE\s+NOCASE/i, '')
        .replace(/^([A-Za-z0-9_]+)/, '"$1"'),
    )
    .join(', ');
  const rest = m[4].replace(/WHERE\s+/i, 'WHERE ');
  lines.push(`CREATE ${unique}INDEX "${idx.name}" ON "${m[2]}" (${colsPart})${rest};`);
}
lines.push('');
lines.push('COMMIT;');

writeFileSync(outPath, lines.join('\n'));
console.log(`已生成 ${tables.length} 张表 / ${indexes.length} 个索引 → ${outPath}`);
const withIdentity = tables.length;
console.log(`提示：COLLATE NOCASE / 触发器需人工补（见 docs/postgres-migration.md）`);
db.close();
